cd /home/thomasphillip/Projects/vox && python3 - <<'EOF'
import json,hashlib
m=json.load(open('.codex/production-runs/2026-09-05-after-the-hearth/implementation-source-manifest.json'))
h=m['hashes']
print(type(h), len(h))
if isinstance(h,dict):
    items=list(h.items())[:2]; print(items)
    bad=[]
    for p,v in h.items():
        want=v if isinstance(v,str) else (v.get('afterSha256') or v.get('sha256'))
        try: got=hashlib.sha256(open(p,'rb').read()).hexdigest()
        except FileNotFoundError: bad.append(('MISSING',p)); continue
        if got!=want: bad.append(('DRIFT',p,want[:8],got[:8]))
    print('mismatch count',len(bad))
    for b in bad[:20]: print(b)
EOF

