    setMusicMuted(true);
    completeTheChapter();
    expect(getCommonGroundScoreDiagnostic().finalTextureSeconds).toBeNull();
    // And it is not queued for a later unlock: unmuting afterwards earns nothing.
    setMusicMuted(false);
    for (let frame = 0; frame < 60; frame += 1) tickCommonGround(0.05);
    expect(getCommonGroundScoreDiagnostic().finalTextureSeconds).toBeNull();
  });

