      if (commonGroundSnapshot().common.comparisonProved) break;
      const plan = harness.frame();
      if (plan.reason !== 'walking the common span' || !plan.target) continue;
      const index = goalVertexIndex(CG_ROUTE_COMMON, plan.target);
