describe('the chapter is four beats and nothing else', () => {
  it('claims exactly its own beats', () => {
    for (const beat of ['ch13-home', 'ch13-return', 'ch13-survey', 'ch13-common'] as const) {
      expect(isCommonGroundBeat(beat), beat).toBe(true);
