    for (const point of CG_ROUTE_LONG.slice(1, 6)) {
      accumulateTraceDistance(snapshot.survey.working, 2);
      appendTraceSample(snapshot.survey.working, { ...point, corner: false });
    }
    markTestedPrefix(snapshot.survey.working, 3);
