    const snapshot = commonGroundSnapshot();
    snapshot.survey.phase = 'drawing';
    snapshot.survey.working = createTraceSlot({ ...CG_ROUTE_LONG[0], corner: true });
    for (const point of CG_ROUTE_LONG.slice(1, 6)) {
