});

describe('the reciprocal claim waits for his body', () => {
  beforeEach(() => enterCommonGroundBeat('ch13-common'));

  const clearOfE = { x: CG_POSES.E.x, y: CG_POSES.E.y, z: CG_POSES.E.z - 3 };

