 * progress a deviation can be given.
 *
 * A body that is further ahead than this did not round a corner — it left the
 * route — and it earns nothing at all until it returns to its own frontier.
 */
export const ROUTE_DEVIATION_ALLOWANCE_UNITS = 0.6;

/**
 * Progress along a fixed authored polyline, in walked units.
 *
 * Endpoint proximity is NOT progress. A body must actually traverse the span,
 * so progress advances only while the body is near the segment it claims to be
 * walking, and never jumps ahead of the segment it has reached.
 *
 * THREE INVARIANTS, and everything else follows from them:
 *
 *   1. Progress never advances by more than the body ACTUALLY moved this frame.
 *   2. Progress never advances past the ordered arc the body has actually
 *      reached, measured at its own closest point on the polyline.
 *   3. Progress never decreases, and never advances at all while the body is
 *      stationary or outside the corridor.
 *
 * Eighteen credited units therefore mean eighteen units really walked inside
 * the corridor, ending at the far end — which is exactly what the span claims.
 *
 * WHY THE FRONTIER RULE CHANGED (recorded manual-corner risk, reproduced from
 * real displacement in `commonGroundRoute.test.ts`). The previous form accepted
 * a projection only if its ABSOLUTE arc fitted under `previousUnits +
 * displacement`, and took the furthest such projection in the corridor. Turning
 * 0.18 units before the first vertex — an ordinary steering error, entirely
 * inside the corridor — put every later projection permanently beyond that
 * ceiling: the measured comparison froze at 4 of 18 units and three hundred
 * further units of walking the actual route recovered NOTHING. The chapter's
 * signed reading forbids both discarding earned progress for a small steering
 * error and crediting the omitted portion for reaching a later segment.
 *
 * So the body's own arc is now read from its CLOSEST point on the polyline (an
 * honest position, not the furthest projection it happens to be near), and the
 * frontier walks toward it at the body's own speed. A rounded corner leaves the
 * frontier fractionally behind, and ordinary further movement closes it; the
 * omitted wedge is still paid for in real distance, and a body that skipped
 * genuine ground is still frozen exactly where it left off.
 */
export function routeProgressUnits(
  route: readonly CommonGroundPoint[],
  body: CommonGroundPoint,
  previousUnits: number,
  displacementUnits: number,
  corridorRadius = 2.5
): number {
  // NO DISPLACEMENT, NO PROGRESS. A stationary body earns nothing, however long
  // it stands there and however many times it is sampled, which is what makes
  // standing at C worth zero and a timer worth nothing at all.
  if (!(displacementUnits > 0)) return previousUnits;
  let travelled = 0;
  let nearest = Number.POSITIVE_INFINITY;
  let arcReached = -1;
  for (let index = 1; index < route.length; index += 1) {
    const from = route[index - 1];
    const to = route[index];
    const segment = distanceBetween(from, to);
    if (segment <= 0) continue;
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const dz = to.z - from.z;
    const t = Math.max(0, Math.min(1,
      ((body.x - from.x) * dx + (body.y - from.y) * dy + (body.z - from.z) * dz)
        / (segment * segment)));
    const closest = { x: from.x + dx * t, y: from.y + dy * t, z: from.z + dz * t };
    const distance = distanceBetween(body, closest);
    // ITS OWN PLACE ON THE ROUTE, not the furthest place it is near. A body two
    // units off a bend is beside ONE piece of ground, and that is the piece its
    // progress is measured from.
    if (distance < nearest) {
      nearest = distance;
      arcReached = travelled + segment * t;
    }
    travelled += segment;
  }
  // Off the route entirely: not walking this span, and earning nothing for it.
  if (arcReached < 0 || nearest > corridorRadius) return previousUnits;
  const lag = arcReached - previousUnits;
  // Behind its own frontier — walking back over ground already credited earns
  // nothing, and walking forward over it again earns nothing either.
  if (lag <= 0) return previousUnits;
  // Further ahead than a rounded corner can explain: this body crossed ground it
  // did not walk. It is frozen at its frontier and must return to it, exactly as
  // before. A single long frame is never punished for being long.
  if (lag > Math.max(displacementUnits, ROUTE_DEVIATION_ALLOWANCE_UNITS)) return previousUnits;
  // The frontier advances at the body's own speed, and never past the body.
  return Math.min(previousUnits + Math.min(displacementUnits, lag), travelled);
}
