      { x: -42, z: 15.82 }, { x: -44, z: 16 }, { x: -44, z: 18 }, { x: -46, z: 18 },
      { x: -48, z: 18 }, { x: -48, z: 16 }, { x: -48, z: 14 }, { x: -48, z: 12 }
    ], CG_POSES.E);
    expect(early.walked).toBeGreaterThan(17.8);
    // It is not frozen at four any more; it is short by the ground it omitted.
    expect(early.units).toBeGreaterThan(17);
    expect(early.units).toBeLessThan(CG_COMMON_ROUTE_UNITS);
